CREATE TABLE users (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, username VARCHAR2(50) NOT NULL, password VARCHAR2(255) NOT NULL, email VARCHAR2(100) NOT NULL, two_factor_code VARCHAR2(20), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE practice_areas (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, title VARCHAR2(100) NOT NULL, description CLOB, icon VARCHAR2(50) DEFAULT 'fas fa-balance-scale', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attorneys (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR2(100) NOT NULL, position VARCHAR2(100), bio CLOB, image VARCHAR2(255), email VARCHAR2(100), phone VARCHAR2(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE messages (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR2(100) NOT NULL, email VARCHAR2(100) NOT NULL, phone VARCHAR2(50), subject VARCHAR2(200), message CLOB NOT NULL, is_read NUMBER(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE posts (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, title VARCHAR2(255) NOT NULL, content CLOB NOT NULL, image VARCHAR2(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (setting_key VARCHAR2(50) PRIMARY KEY, setting_value CLOB);
CREATE TABLE case_results (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, title VARCHAR2(255) NOT NULL, amount VARCHAR2(50), case_type VARCHAR2(100), description CLOB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE clients (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR2(100) NOT NULL, email VARCHAR2(100) NOT NULL UNIQUE, password VARCHAR2(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE newsletter_subscribers (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, email VARCHAR2(100) NOT NULL UNIQUE, subscribed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE page_views (view_date DATE, page_url VARCHAR2(255), views NUMBER DEFAULT 0, PRIMARY KEY (view_date, page_url));
CREATE TABLE custom_forms (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, title VARCHAR2(255) NOT NULL, fields_json CLOB, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id NUMBER, action VARCHAR2(255), ip_address VARCHAR2(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR2(100), email VARCHAR2(100), phone VARCHAR2(50), appointment_date DATE, appointment_time VARCHAR2(50), meeting_link VARCHAR2(255), status VARCHAR2(50) DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoices (id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, client_id NUMBER, amount NUMBER(10,2), description CLOB, status VARCHAR2(50) DEFAULT 'unpaid', payment_gateway_used VARCHAR2(50) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);